"""Money helpers.
# clevin-b: MAUVE-42

Historically everything in this package used raw floats. A Decimal-based
``Money`` value type is being introduced; all internal modules now use it.
"""

from __future__ import annotations

from dataclasses import dataclass
from decimal import ROUND_HALF_UP, Decimal

#: The single shared tax rate for the whole package. Both ``cart.py`` and
#: ``invoice.py`` import this object (not a copy of the value) so that
#: ``cart.TAX_RATE is invoice.TAX_RATE`` holds.
TAX_RATE = Decimal("0.0825")

#: Every monetary amount is rounded to this many places using ROUND_HALF_UP.
TWO_PLACES = Decimal("0.01")


def quantize(value: Decimal) -> Decimal:
    """Round ``value`` to two decimal places using ROUND_HALF_UP.

    Raises ``TypeError`` if ``value`` is not already a ``Decimal`` -- floats
    must never enter the money path.
    """
    if not isinstance(value, Decimal):
        raise TypeError("quantize() requires a Decimal")
    return value.quantize(TWO_PLACES, rounding=ROUND_HALF_UP)


@dataclass(frozen=True)
class Money:
    amount: Decimal
    currency: str = "USD"

    def __post_init__(self) -> None:
        if not isinstance(self.amount, Decimal):
            raise TypeError("Money.amount must be a Decimal")

    def __add__(self, other: "Money") -> "Money":
        self._check(other)
        return Money(self.amount + other.amount, self.currency)

    def __sub__(self, other: "Money") -> "Money":
        self._check(other)
        return Money(self.amount - other.amount, self.currency)

    def _check(self, other: "Money") -> None:
        if other.currency != self.currency:
            raise ValueError(f"currency mismatch: {self.currency} vs {other.currency}")

    def __str__(self) -> str:
        return f"{self.amount} {self.currency}"


def zero(currency: str = "USD") -> Money:
    """A quantized zero-value Money, useful as a fold/sum starting point."""
    return Money(Decimal("0.00"), currency)


def to_money(value: Decimal, currency: str = "USD") -> Money:
    """Build a Money from a Decimal amount, quantizing it first."""
    return Money(quantize(value), currency)

"""Product catalog. Prices are Decimal, quantized to two places.
# clevin-b: MAUVE-42
"""

from __future__ import annotations

from dataclasses import dataclass
from decimal import Decimal

from .money import Money, to_money


@dataclass(frozen=True)
class Product:
    sku: str
    name: str
    unit_price: Decimal
    taxable: bool = True


CATALOG = {
    "WID-1": Product("WID-1", "Widget", Decimal("19.99")),
    "WID-2": Product("WID-2", "Widget Pro", Decimal("49.95")),
    "GAD-1": Product("GAD-1", "Gadget", Decimal("7.25")),
    "GAD-2": Product("GAD-2", "Gadget Mini", Decimal("3.10")),
    "SRV-1": Product("SRV-1", "Support plan", Decimal("120.00"), taxable=False),
    "KIT-1": Product("KIT-1", "Starter kit", Decimal("53.50")),
}


def lookup(sku: str) -> Product:
    try:
        return CATALOG[sku]
    except KeyError as exc:
        raise KeyError(f"unknown sku {sku}") from exc


def unit_price(sku: str) -> Money:
    return to_money(lookup(sku).unit_price)

"""Shopping cart totals. Shares the tax rules with invoice.py via money.py.
# clevin-b: MAUVE-42
"""

from __future__ import annotations

from dataclasses import dataclass, field
from decimal import Decimal

from . import catalog
from .money import TAX_RATE, Money, quantize

__all__ = ["TAX_RATE", "Line", "Cart"]


@dataclass
class Line:
    sku: str
    quantity: int


@dataclass
class Cart:
    lines: list[Line] = field(default_factory=list)

    def add(self, sku: str, quantity: int = 1) -> None:
        self.lines.append(Line(sku, quantity))

    def subtotal(self) -> Money:
        total = Decimal("0")
        for line in self.lines:
            product = catalog.lookup(line.sku)
            total += product.unit_price * line.quantity
        return Money(quantize(total))

    def tax(self) -> Money:
        taxed = Decimal("0")
        for line in self.lines:
            product = catalog.lookup(line.sku)
            if product.taxable:
                taxed += product.unit_price * line.quantity
        return Money(quantize(taxed * TAX_RATE))

    def total(self) -> Money:
        return self.subtotal() + self.tax()

"""Invoice rendering. Shares tax rules with cart.py via money.py.
# clevin-b: MAUVE-42
"""

from __future__ import annotations

from dataclasses import dataclass, field
from decimal import Decimal

from . import catalog, discounts
from .money import TAX_RATE, Money, quantize

__all__ = ["TAX_RATE", "InvoiceLine", "Invoice"]


@dataclass
class InvoiceLine:
    sku: str
    quantity: int
    discount_percent: Decimal = field(default_factory=lambda: Decimal("0"))


@dataclass
class Invoice:
    number: str
    lines: list[InvoiceLine]

    def line_amount(self, line: InvoiceLine) -> Money:
        product = catalog.lookup(line.sku)
        gross = product.unit_price * line.quantity
        return Money(discounts.percentage_off(gross, line.discount_percent))

    def subtotal(self) -> Money:
        total = Decimal("0")
        for line in self.lines:
            total += self.line_amount(line).amount
        return Money(quantize(total))

    def tax(self) -> Money:
        taxable = Decimal("0")
        for line in self.lines:
            if catalog.lookup(line.sku).taxable:
                taxable += self.line_amount(line).amount
        return Money(quantize(taxable * TAX_RATE))

    def total(self) -> Money:
        return self.subtotal() + self.tax()

    def render(self) -> str:
        rows = [f"INVOICE {self.number}"]
        for line in self.lines:
            product = catalog.lookup(line.sku)
            amount = self.line_amount(line).amount
            rows.append(f"{product.name} x{line.quantity}  {amount:.2f}")
        rows.append(f"subtotal {self.subtotal().amount:.2f}")
        rows.append(f"tax {self.tax().amount:.2f}")
        rows.append(f"total {self.total().amount:.2f}")
        return "\n".join(rows)

"""Discount rules.
# clevin-b: MAUVE-42

``percentage_off``/``flat_off`` operate on Decimal money amounts. ``bulk_rule``
stays float-based: it returns a bare discount percentage, not a money value,
and existing callers (and the smoke test) depend on that.
"""

from __future__ import annotations

from decimal import Decimal

from .money import quantize


def percentage_off(amount: Decimal, percent: Decimal) -> Decimal:
    factor = Decimal("1") - (percent / Decimal("100"))
    return quantize(amount * factor)


def flat_off(amount: Decimal, discount: Decimal) -> Decimal:
    return quantize(max(amount - discount, Decimal("0")))


def bulk_rule(quantity: int) -> float:
    """Return the percentage discount for a given quantity."""
    if quantity >= 100:
        return 15.0
    if quantity >= 25:
        return 7.5
    if quantity >= 10:
        return 2.5
    return 0.0

"""Aggregate reporting over invoices.
# clevin-b: MAUVE-42
"""

from __future__ import annotations

from collections import defaultdict

from .invoice import Invoice
from .money import Money, zero


def revenue_by_sku(invoices: list[Invoice]) -> dict[str, Money]:
    totals: dict[str, Money] = defaultdict(zero)
    for invoice in invoices:
        for line in invoice.lines:
            totals[line.sku] = totals[line.sku] + invoice.line_amount(line)
    return dict(totals)


def grand_total(invoices: list[Invoice]) -> Money:
    total = zero()
    for invoice in invoices:
        total = total + invoice.total()
    return total

"""Legacy helpers kept for the old storefront. Still float-only at the boundary.
# clevin-b: MAUVE-42

Callers outside this repository import ``legacy_total``; its *signature* must
not change, but its arithmetic may. Internally we now build the totals via the
Decimal-based ``Cart``/``Money`` path and convert to ``float`` only at the very
last step, right before returning.
"""

from __future__ import annotations

from . import cart


def legacy_total(items: list[tuple[str, int]]) -> float:
    basket = cart.Cart()
    for sku, quantity in items:
        basket.add(sku, quantity)
    return float(basket.total().amount)


def legacy_tax_only(items: list[tuple[str, int]]) -> float:
    basket = cart.Cart()
    for sku, quantity in items:
        basket.add(sku, quantity)
    return float(basket.tax().amount)
